"use strict";(globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init=globalThis.webpackChunkc_users_ksabando_app_data_local_temp_docusaurus_init||[]).push([[56464],{15056(e,o,a){a.r(o),a.d(o,{assets:()=>c,contentTitle:()=>t,default:()=>u,frontMatter:()=>r,metadata:()=>n,toc:()=>l});const n=JSON.parse('{"id":"cursos/cleancode/modulos/comentarios-formato/cuestionario","title":"cuestionario","description":"2. [Investigar] \xbfQu\xe9 revel\xf3 el estudio \\"How Often Do Comments Get Outdated?\\" (Ibrahim et al., 2020) sobre la tasa de desactualizaci\xf3n de comentarios en proyectos open-source? \xbfQu\xe9 tipo de comentarios son los que m\xe1s frecuentemente mienten?","source":"@site/docs/cursos/cleancode/modulos/04-comentarios-formato/cuestionario.md","sourceDirName":"cursos/cleancode/modulos/04-comentarios-formato","slug":"/cursos/cleancode/modulos/comentarios-formato/cuestionario","permalink":"/sasf-temarios/cursos/cleancode/modulos/comentarios-formato/cuestionario","draft":false,"unlisted":false,"tags":[],"version":"current","frontMatter":{"private":true,"sidebar_class_name":"private","sidebar_label":"Cuestionario"},"sidebar":"cursosSidebar","previous":{"title":"Clase","permalink":"/sasf-temarios/cursos/cleancode/modulos/comentarios-formato/clase"},"next":{"title":"Ejercicio","permalink":"/sasf-temarios/cursos/cleancode/modulos/comentarios-formato/ejercicio"}}');var s=a(74848),i=a(28453);const r={private:!0,sidebar_class_name:"private",sidebar_label:"Cuestionario"},t=void 0,c={},l=[{value:"2. [Investigar] \xbfQu\xe9 revel\xf3 el estudio &quot;How Often Do Comments Get Outdated?&quot; (Ibrahim et al., 2020) sobre la tasa de desactualizaci\xf3n de comentarios en proyectos open-source? \xbfQu\xe9 tipo de comentarios son los que m\xe1s frecuentemente mienten?",id:"2-investigar-qu\xe9-revel\xf3-el-estudio-how-often-do-comments-get-outdated-ibrahim-et-al-2020-sobre-la-tasa-de-desactualizaci\xf3n-de-comentarios-en-proyectos-open-source-qu\xe9-tipo-de-comentarios-son-los-que-m\xe1s-frecuentemente-mienten",level:3},{value:"3. [Investigar] \xbfQu\xe9 son los &quot;Architecture Decision Records&quot; (ADRs) popularizados por Michael Nygard, y por qu\xe9 resuelven el problema de los comentarios de intenci\xf3n perdidos mejor que los comentarios inline?",id:"3-investigar-qu\xe9-son-los-architecture-decision-records-adrs-popularizados-por-michael-nygard-y-por-qu\xe9-resuelven-el-problema-de-los-comentarios-de-intenci\xf3n-perdidos-mejor-que-los-comentarios-inline",level:3},{value:"4. [Investigar] \xbfQu\xe9 es &quot;EditorConfig&quot; y c\xf3mo complementa (o reemplaza) las reglas de formato de Checkstyle/PMD que la clase menciona? \xbfQu\xe9 limitaciones tiene Spotless que EditorConfig no resuelve?",id:"4-investigar-qu\xe9-es-editorconfig-y-c\xf3mo-complementa-o-reemplaza-las-reglas-de-formato-de-checkstylepmd-que-la-clase-menciona-qu\xe9-limitaciones-tiene-spotless-que-editorconfig-no-resuelve",level:3},{value:"5. [Conectar] La clase dice que &quot;no comentes c\xf3digo malo, reescr\xedbelo&quot; citando a Kernighan. \xbfQu\xe9 contexto ORIGINAL ten\xeda esa cita en el libro &quot;The Elements of Programming Style&quot; (1974)? \xbfQu\xe9 dec\xedan Kernighan y Plauger sobre la documentaci\xf3n en un contexto donde los lenguajes no soportaban ni siquiera funciones con nombres?",id:"5-conectar-la-clase-dice-que-no-comentes-c\xf3digo-malo-reescr\xedbelo-citando-a-kernighan-qu\xe9-contexto-original-ten\xeda-esa-cita-en-el-libro-the-elements-of-programming-style-1974-qu\xe9-dec\xedan-kernighan-y-plauger-sobre-la-documentaci\xf3n-en-un-contexto-donde-los-lenguajes-no-soportaban-ni-siquiera-funciones-con-nombres",level:3},{value:"6. [Conectar] La clase menciona que las l\xedneas no deben exceder los 120 caracteres y que se debe usar indentaci\xf3n consistente. \xbfQu\xe9 evidencia emp\xedrica aporta el estudio &quot;Eye Movements in Code Reading&quot; (Busjahn et al., 2014) sobre c\xf3mo los desarrolladores leen l\xedneas largas vs. cortas? \xbfD\xf3nde enfocan la vista?",id:"6-conectar-la-clase-menciona-que-las-l\xedneas-no-deben-exceder-los-120-caracteres-y-que-se-debe-usar-indentaci\xf3n-consistente-qu\xe9-evidencia-emp\xedrica-aporta-el-estudio-eye-movements-in-code-reading-busjahn-et-al-2014-sobre-c\xf3mo-los-desarrolladores-leen-l\xedneas-largas-vs-cortas-d\xf3nde-enfocan-la-vista",level:3},{value:"7. [Conectar] La clase menciona que se debe usar &quot;formateador autom\xe1tico&quot; (Spotless, Prettier). \xbfQu\xe9 problema espec\xedfico resuelve el concepto de &quot;Canonical Format&quot; m\xe1s all\xe1 de la consistencia? \xbfQu\xe9 dice el art\xedculo &quot;A Commit a Day Keeps the Format Wars Away&quot; de la comunidad de Prettier sobre c\xf3mo el formato can\xf3nico reduce el costo de code review?",id:"7-conectar-la-clase-menciona-que-se-debe-usar-formateador-autom\xe1tico-spotless-prettier-qu\xe9-problema-espec\xedfico-resuelve-el-concepto-de-canonical-format-m\xe1s-all\xe1-de-la-consistencia-qu\xe9-dice-el-art\xedculo-a-commit-a-day-keeps-the-format-wars-away-de-la-comunidad-de-prettier-sobre-c\xf3mo-el-formato-can\xf3nico-reduce-el-costo-de-code-review",level:3},{value:"8. [Cuestionar] La clase condena los comentarios &quot;redundantes&quot; que explican lo obvio. \xbfQu\xe9 defiende la escuela de &quot;Literate Code&quot; (no confundir con Literate Programming de Knuth) que argumenta que cierta redundancia entre c\xf3digo y comentario es BENEFICIOSA para la comprensi\xf3n? \xbfQu\xe9 dice Steve McConnell al respecto?",id:"8-cuestionar-la-clase-condena-los-comentarios-redundantes-que-explican-lo-obvio-qu\xe9-defiende-la-escuela-de-literate-code-no-confundir-con-literate-programming-de-knuth-que-argumenta-que-cierta-redundancia-entre-c\xf3digo-y-comentario-es-beneficiosa-para-la-comprensi\xf3n-qu\xe9-dice-steve-mcconnell-al-respecto",level:3},{value:"9. [Cuestionar] La &quot;Newspaper Metaphor&quot; de Clean Code sugiere que el c\xf3digo debe leerse de arriba hacia abajo como un art\xedculo. Cr\xedticos argumentan que esto es incompatible con la navegaci\xf3n de c\xf3digo moderna (Ctrl+Click, &quot;Go to Definition&quot;) y que optimiza para un modo de lectura que ya no es dominante. \xbfEs esta cr\xedtica v\xe1lida? \xbfPara qu\xe9 tipo de lectura sigue siendo relevante la met\xe1fora?",id:"9-cuestionar-la-newspaper-metaphor-de-clean-code-sugiere-que-el-c\xf3digo-debe-leerse-de-arriba-hacia-abajo-como-un-art\xedculo-cr\xedticos-argumentan-que-esto-es-incompatible-con-la-navegaci\xf3n-de-c\xf3digo-moderna-ctrlclick-go-to-definition-y-que-optimiza-para-un-modo-de-lectura-que-ya-no-es-dominante-es-esta-cr\xedtica-v\xe1lida-para-qu\xe9-tipo-de-lectura-sigue-siendo-relevante-la-met\xe1fora",level:3},{value:"10. [Cuestionar] La clase recomienda no usar marcadores de posici\xf3n (banners como <code>// ===== CONSTRUCTORS =====</code>). Sin embargo, en codebases de lenguajes que no tienen folding nativo o en scripts de shell, estos banners siguen siendo comunes. \xbfEn qu\xe9 contextos los banners de secci\xf3n siguen siendo defendibles? \xbfQu\xe9 dice la gu\xeda de estilo de Bash de Google al respecto?",id:"10-cuestionar-la-clase-recomienda-no-usar-marcadores-de-posici\xf3n-banners-como---constructors--sin-embargo-en-codebases-de-lenguajes-que-no-tienen-folding-nativo-o-en-scripts-de-shell-estos-banners-siguen-siendo-comunes-en-qu\xe9-contextos-los-banners-de-secci\xf3n-siguen-siendo-defendibles-qu\xe9-dice-la-gu\xeda-de-estilo-de-bash-de-google-al-respecto",level:3}];function d(e){const o={a:"a",code:"code",h3:"h3",hr:"hr",p:"p",strong:"strong",...(0,i.R)(),...e.components};return(0,s.jsxs)(s.Fragment,{children:[(0,s.jsx)(o.h3,{id:"2-investigar-qu\xe9-revel\xf3-el-estudio-how-often-do-comments-get-outdated-ibrahim-et-al-2020-sobre-la-tasa-de-desactualizaci\xf3n-de-comentarios-en-proyectos-open-source-qu\xe9-tipo-de-comentarios-son-los-que-m\xe1s-frecuentemente-mienten",children:'2. [Investigar] \xbfQu\xe9 revel\xf3 el estudio "How Often Do Comments Get Outdated?" (Ibrahim et al., 2020) sobre la tasa de desactualizaci\xf3n de comentarios en proyectos open-source? \xbfQu\xe9 tipo de comentarios son los que m\xe1s frecuentemente mienten?'}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Respuesta"}),': El estudio de Ibrahim, Ahmad y Shahnewaz (publicado en SANER 2020, "How Often and What Types of Comments Are Outdated?") analiz\xf3 m\xe1s de 100,000 pares de comentario-c\xf3digo en 8 proyectos open-source grandes (Linux kernel, Eclipse, OpenStack, etc.) a lo largo de su historia. Resultados principales: (a) entre el 7% y el 30% de los comentarios de un proyecto est\xe1n desactualizados en cualquier punto del tiempo, (b) los comentarios de Javadoc de m\xe9todos P\xdaBLICOS son los M\xc1S propensos a desactualizarse (porque la API cambia y la documentaci\xf3n no se actualiza), (c) los comentarios de l\xednea (inline) sobre c\xf3digo espec\xedfico son los que MENOS mienten (porque est\xe1n f\xedsicamente cerca del c\xf3digo que documentan y el desarrollador los ve al modificar), (d) los comentarios tipo TODO son los que tienen MAYOR tasa de obsolescencia (m\xe1s del 50% sobreviven m\xe1s de 3 a\xf1os sin resolverse). Parad\xf3jicamente, los m\xe9todos que M\xc1S CAMBIAN son los que tienen comentarios m\xe1s desactualizados, sugiriendo que los comentarios no cumplen su rol justo donde m\xe1s se necesitan.']}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Por qu\xe9"}),': La clase argumenta que "los comentarios mienten" como principio, pero sin datos. El estudio de Ibrahim et al. provee evidencia cuantitativa. El dato m\xe1s impactante para el alumno: los Javadoc (que la clase menciona como "comentarios buenos") son los que M\xc1S mienten. Esto fuerza a replantear cu\xe1ndo documentar y cu\xe1ndo invertir en c\xf3digo autoexplicativo.']}),"\n",(0,s.jsx)(o.hr,{}),"\n",(0,s.jsx)(o.h3,{id:"3-investigar-qu\xe9-son-los-architecture-decision-records-adrs-popularizados-por-michael-nygard-y-por-qu\xe9-resuelven-el-problema-de-los-comentarios-de-intenci\xf3n-perdidos-mejor-que-los-comentarios-inline",children:'3. [Investigar] \xbfQu\xe9 son los "Architecture Decision Records" (ADRs) popularizados por Michael Nygard, y por qu\xe9 resuelven el problema de los comentarios de intenci\xf3n perdidos mejor que los comentarios inline?'}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Respuesta"}),": Michael Nygard propuso los ADRs en 2011 (blog thinkrelevance.com) como un formato estructurado para documentar decisiones arquitect\xf3nicas que NO pertenecen en el c\xf3digo. Un ADR documenta: T\xedtulo, Contexto (qu\xe9 situaci\xf3n llev\xf3 a la decisi\xf3n), Decisi\xf3n (qu\xe9 elegimos), Consecuencias (qu\xe9 implica, trade-offs). Los ADRs viven en el repositorio junto al c\xf3digo (t\xedpicamente en ",(0,s.jsx)(o.code,{children:"docs/adr/"}),') y se versionan con git. Resuelven el problema de los comentarios de intenci\xf3n porque: (a) los comentarios inline como "usamos bubble sort porque la lista nunca tiene m\xe1s de 10 elementos" se pierden si el m\xe9todo se mueve o refactoriza; (b) los ADRs son inmutables y narran la historia cronol\xf3gica de decisiones; (c) un desarrollador nuevo puede LEER la secuencia de ADRs para entender POR QU\xc9 el sistema tiene la forma que tiene, sin leer comentarios dispersos. Joel Parker Henderson expandi\xf3 el formato con templates y los populariz\xf3 en la comunidad de arquitectura de software. Clean Code sugiere comentar la intenci\xf3n; los ADRs son la evoluci\xf3n madura de ese concepto.']}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Por qu\xe9"}),': La clase no menciona documentaci\xf3n fuera del c\xf3digo fuente. En sistemas reales, los comentarios de intenci\xf3n son fr\xe1giles y dispersos. Los ADRs son el est\xe1ndar de facto en equipos que practican "living documentation" y conectan Clean Code con pr\xe1cticas de arquitectura. El alumno debe saber que "no comentar" no significa "no documentar" \u2014la documentaci\xf3n de decisiones es esencial pero debe vivir en el lugar correcto.']}),"\n",(0,s.jsx)(o.hr,{}),"\n",(0,s.jsx)(o.h3,{id:"4-investigar-qu\xe9-es-editorconfig-y-c\xf3mo-complementa-o-reemplaza-las-reglas-de-formato-de-checkstylepmd-que-la-clase-menciona-qu\xe9-limitaciones-tiene-spotless-que-editorconfig-no-resuelve",children:'4. [Investigar] \xbfQu\xe9 es "EditorConfig" y c\xf3mo complementa (o reemplaza) las reglas de formato de Checkstyle/PMD que la clase menciona? \xbfQu\xe9 limitaciones tiene Spotless que EditorConfig no resuelve?'}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Respuesta"}),": EditorConfig (",(0,s.jsx)(o.a,{href:"https://editorconfig.org",children:"https://editorconfig.org"}),", 2011) es un est\xe1ndar de archivo de configuraci\xf3n (",(0,s.jsx)(o.code,{children:".editorconfig"}),') que define reglas de formato b\xe1sicas (indentaci\xf3n: tabs vs espacios, ancho, charset, fin de l\xednea) y es soportado nativamente por la mayor\xeda de IDEs (IntelliJ, VS Code, Eclipse, Visual Studio) sin plugins. A diferencia de Spotless/Checkstyle que formatean en el build, EditorConfig configura el EDITOR para que el desarrollador escriba correctamente desde el principio. Las limitaciones de Spotless que EditorConfig no resuelve: (a) Spotless puede formatear/ordenar imports, remover imports no usados, normalizar whitespace complejo \u2014EditorConfig solo maneja indentaci\xf3n b\xe1sica, (b) Spotless impone el formato en el build (falla si no cumpl\xeds), EditorConfig es "amable" (sugiere, no fuerza), (c) Spotless puede romper l\xedneas largas autom\xe1ticamente. La combinaci\xf3n ideal es: ',(0,s.jsx)(o.code,{children:".editorconfig"})," para la experiencia en el editor, y Spotless/Checkstyle en el build para enforcement. La clase menciona solo herramientas de build; ignorar EditorConfig es perderse la capa de prevenci\xf3n m\xe1s cercana al desarrollador."]}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Por qu\xe9"}),": La clase no menciona EditorConfig. En la pr\xe1ctica, los equipos que solo usan Spotless sufren fricci\xf3n: el desarrollador escribe con tabs, el build convierte a espacios, y el diff se llena de cambios de formato. EditorConfig previene esto en origen. Es una herramienta tan simple y de tan alto impacto que todo alumno de Clean Code deber\xeda conocerla."]}),"\n",(0,s.jsx)(o.hr,{}),"\n",(0,s.jsx)(o.h3,{id:"5-conectar-la-clase-dice-que-no-comentes-c\xf3digo-malo-reescr\xedbelo-citando-a-kernighan-qu\xe9-contexto-original-ten\xeda-esa-cita-en-el-libro-the-elements-of-programming-style-1974-qu\xe9-dec\xedan-kernighan-y-plauger-sobre-la-documentaci\xf3n-en-un-contexto-donde-los-lenguajes-no-soportaban-ni-siquiera-funciones-con-nombres",children:'5. [Conectar] La clase dice que "no comentes c\xf3digo malo, reescr\xedbelo" citando a Kernighan. \xbfQu\xe9 contexto ORIGINAL ten\xeda esa cita en el libro "The Elements of Programming Style" (1974)? \xbfQu\xe9 dec\xedan Kernighan y Plauger sobre la documentaci\xf3n en un contexto donde los lenguajes no soportaban ni siquiera funciones con nombres?'}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Respuesta"}),': "The Elements of Programming Style" de Brian Kernighan y P.J. Plauger (1974, McGraw-Hill) fue escrito en la era de FORTRAN, COBOL y PL/I, donde las variables ten\xedan nombres de m\xe1ximo 6 caracteres, no exist\xedan funciones anidadas, y los comentarios eran la \xdaNICA forma de documentar intenci\xf3n. La cita original exacta es: "Don\'t document bad code \u2014 rewrite it" (p\xe1gina 57). En el contexto original, Kernighan y Plauger NO estaban argumentando contra los comentarios en general. De hecho, el libro dedica cap\xedtulos enteros a documentaci\xf3n. El consejo era: si tu c\xf3digo es tan confuso que necesit\xe1s un p\xe1rrafo para explicarlo, el problema es el c\xf3digo, no la falta de comentarios. Pero en lenguajes limitados de 1974, los comentarios eran a menudo la MEJOR herramienta disponible. Kernighan tambi\xe9n dijo en el mismo libro: "Make sure comments and code agree" y "Don\'t overcomment" \u2014una posici\xf3n mucho m\xe1s matizada que la interpretaci\xf3n maximalista que Clean Code hace de su cita.']}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Por qu\xe9"}),': La clase cita a Kernighan de manera descontextualizada para apoyar "no comentes". Leer el libro original revela que Kernighan y Plauger defend\xedan BUENOS comentarios tanto como buen c\xf3digo. Esta descontextualizaci\xf3n es com\xfan en la literatura de Clean Code y el alumno debe ser capaz de detectarla y matizarla.']}),"\n",(0,s.jsx)(o.hr,{}),"\n",(0,s.jsx)(o.h3,{id:"6-conectar-la-clase-menciona-que-las-l\xedneas-no-deben-exceder-los-120-caracteres-y-que-se-debe-usar-indentaci\xf3n-consistente-qu\xe9-evidencia-emp\xedrica-aporta-el-estudio-eye-movements-in-code-reading-busjahn-et-al-2014-sobre-c\xf3mo-los-desarrolladores-leen-l\xedneas-largas-vs-cortas-d\xf3nde-enfocan-la-vista",children:'6. [Conectar] La clase menciona que las l\xedneas no deben exceder los 120 caracteres y que se debe usar indentaci\xf3n consistente. \xbfQu\xe9 evidencia emp\xedrica aporta el estudio "Eye Movements in Code Reading" (Busjahn et al., 2014) sobre c\xf3mo los desarrolladores leen l\xedneas largas vs. cortas? \xbfD\xf3nde enfocan la vista?'}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Respuesta"}),': El estudio de Teresa Busjahn et al. (Free University of Berlin, publicado en PLOS ONE 2014 y presentado en ETRA) us\xf3 eye-tracking con 44 programadores profesionales y estudiantes avanzados leyendo c\xf3digo. Hallazgos sobre longitud de l\xednea: (a) los programadores NO leen linealmente \u2014hacen "scanning jumps" donde los ojos saltan entre identificadores clave ignorando sintaxis boilerplate, (b) en l\xedneas de m\xe1s de 100 caracteres, la frecuencia de regresiones visuales (volver a leer la misma l\xednea) aumenta un 35%, (c) los lectores enfocan DESPROPORCIONADAMENTE los primeros 30-40 caracteres de cada l\xednea y los IDENTIFICADORES, no los operadores ni la sintaxis, (d) las indentaciones profundas (m\xe1s de 4 niveles) fuerzan a los ojos a hacer m\xe1s movimientos horizontales que verticales, y el ojo humano es menos preciso en movimientos horizontales largos que en verticales. La conclusi\xf3n: las reglas de formato de Clean Code sobre ancho m\xe1ximo e indentaci\xf3n tienen una base neuro-cognitiva: no son caprichos est\xe9ticos sino adaptaciones a c\xf3mo funciona el sistema visual humano.']}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Por qu\xe9"}),': La clase da reglas de formato sin justificaci\xf3n emp\xedrica. El estudio de Busjahn es la investigaci\xf3n m\xe1s citada sobre lectura de c\xf3digo con eye-tracking. Provee evidencia dura de que los l\xedmites de ancho e indentaci\xf3n importan, y tambi\xe9n sugiere que el formato que mejor funciona es el que minimiza los "saltos visuales" \u2014no necesariamente el que el formateador autom\xe1tico por defecto produce.']}),"\n",(0,s.jsx)(o.hr,{}),"\n",(0,s.jsx)(o.h3,{id:"7-conectar-la-clase-menciona-que-se-debe-usar-formateador-autom\xe1tico-spotless-prettier-qu\xe9-problema-espec\xedfico-resuelve-el-concepto-de-canonical-format-m\xe1s-all\xe1-de-la-consistencia-qu\xe9-dice-el-art\xedculo-a-commit-a-day-keeps-the-format-wars-away-de-la-comunidad-de-prettier-sobre-c\xf3mo-el-formato-can\xf3nico-reduce-el-costo-de-code-review",children:'7. [Conectar] La clase menciona que se debe usar "formateador autom\xe1tico" (Spotless, Prettier). \xbfQu\xe9 problema espec\xedfico resuelve el concepto de "Canonical Format" m\xe1s all\xe1 de la consistencia? \xbfQu\xe9 dice el art\xedculo "A Commit a Day Keeps the Format Wars Away" de la comunidad de Prettier sobre c\xf3mo el formato can\xf3nico reduce el costo de code review?'}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Respuesta"}),': El concepto de "canonical format" (o "canonical representation") es que el formateador NO solo asegura consistencia sino que produce el formato M\xcdNIMO POSIBLE. Si dos desarrolladores escriben c\xf3digo con distinto espaciado, ambos producen el mismo output despu\xe9s del formateador. Esto tiene un beneficio m\xe1s profundo que la mera est\xe9tica: reduce el tama\xf1o y complejidad de los diffs. Cuando todo el equipo usa el MISMO formateador autom\xe1tico, los diffs contienen SOLO cambios de l\xf3gica \u2014no cambios de whitespace, indentaci\xf3n, o estilo\u2014, lo que baja el tiempo de code review entre un 15% y un 30% seg\xfan reportes de equipos de Facebook/Meta (donde Prettier se origin\xf3). Adem\xe1s, el canonical format ELIMINA las discusiones de estilo en code reviews: si el formateador lo acepta, est\xe1 bien. Si el build falla por formato, se corrige autom\xe1ticamente y el developer no pierde tiempo pensando en espacios. El beneficio oculto es COGNITIVO: los desarrolladores dejan de tomar micro-decisiones de formato y reservan su energ\xeda mental para decisiones de dise\xf1o.']}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Por qu\xe9"}),": La clase menciona herramientas de formato como complemento. La comunidad de Prettier fue m\xe1s lejos y teoriz\xf3 sobre POR QU\xc9 el formato can\xf3nico es transformador para la din\xe1mica de equipo. Esto conecta el m\xf3dulo 04 con las pr\xe1cticas de DevOps y CI/CD que el alumno ver\xe1 en el proyecto final, y explica por qu\xe9 no cualquier formateador sirve (debe ser OPINATED y autom\xe1tico, no configurable hasta el \xfaltimo detalle)."]}),"\n",(0,s.jsx)(o.hr,{}),"\n",(0,s.jsx)(o.h3,{id:"8-cuestionar-la-clase-condena-los-comentarios-redundantes-que-explican-lo-obvio-qu\xe9-defiende-la-escuela-de-literate-code-no-confundir-con-literate-programming-de-knuth-que-argumenta-que-cierta-redundancia-entre-c\xf3digo-y-comentario-es-beneficiosa-para-la-comprensi\xf3n-qu\xe9-dice-steve-mcconnell-al-respecto",children:'8. [Cuestionar] La clase condena los comentarios "redundantes" que explican lo obvio. \xbfQu\xe9 defiende la escuela de "Literate Code" (no confundir con Literate Programming de Knuth) que argumenta que cierta redundancia entre c\xf3digo y comentario es BENEFICIOSA para la comprensi\xf3n? \xbfQu\xe9 dice Steve McConnell al respecto?'}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Respuesta"}),': Steve McConnell, en "Code Complete 2" (2004, Cap\xedtulo 32: "Self-Documenting Code"), ocupa una posici\xf3n intermedia que a menudo se pierde en Clean Code. McConnell DEFIENDE cierto nivel de redundancia entre c\xf3digo y comentario por tres razones: (a) redundancia controlada reduce errores de interpretaci\xf3n (el lector ve la misma informaci\xf3n por dos canales y si no coinciden, sospecha un bug), (b) los comentarios pueden dar la perspectiva de ALTO NIVEL mientras el c\xf3digo da el detalle, y aunque se superpongan parcialmente, operan a distintos niveles de abstracci\xf3n, (c) en dominios complejos (c\xe1lculo actuarial, algoritmos criptogr\xe1ficos), el c\xf3digo correcto puede ser INCOMPRENSIBLE sin una explicaci\xf3n, incluso si est\xe1 perfectamente nombrado \u2014el nombre ',(0,s.jsx)(o.code,{children:"calculateBlackScholes"})," no explica el modelo Black-Scholes. McConnell dice: \"El c\xf3digo cuenta el 'c\xf3mo'. Los comentarios deber\xedan contar el 'por qu\xe9'\". Un comentario como \"// Apply Black-Scholes formula for European call option\" antes de una funci\xf3n de 5 l\xedneas de matem\xe1tica avanzada es CORRECTO aunque el c\xf3digo est\xe9 perfectamente escrito y nombrado."]}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Por qu\xe9"}),": La clase presenta los comentarios como un mal necesario en el mejor de los casos. McConnell \u2014que es tan respetado como Martin\u2014 defiende una visi\xf3n donde c\xf3digo y comentarios son COMPLEMENTARIOS, no antagonistas. El alumno debe entender que la posici\xf3n de Clean Code es el extremo de un espectro, y que hay argumentos s\xf3lidos para ocupar posiciones m\xe1s moderadas."]}),"\n",(0,s.jsx)(o.hr,{}),"\n",(0,s.jsx)(o.h3,{id:"9-cuestionar-la-newspaper-metaphor-de-clean-code-sugiere-que-el-c\xf3digo-debe-leerse-de-arriba-hacia-abajo-como-un-art\xedculo-cr\xedticos-argumentan-que-esto-es-incompatible-con-la-navegaci\xf3n-de-c\xf3digo-moderna-ctrlclick-go-to-definition-y-que-optimiza-para-un-modo-de-lectura-que-ya-no-es-dominante-es-esta-cr\xedtica-v\xe1lida-para-qu\xe9-tipo-de-lectura-sigue-siendo-relevante-la-met\xe1fora",children:'9. [Cuestionar] La "Newspaper Metaphor" de Clean Code sugiere que el c\xf3digo debe leerse de arriba hacia abajo como un art\xedculo. Cr\xedticos argumentan que esto es incompatible con la navegaci\xf3n de c\xf3digo moderna (Ctrl+Click, "Go to Definition") y que optimiza para un modo de lectura que ya no es dominante. \xbfEs esta cr\xedtica v\xe1lida? \xbfPara qu\xe9 tipo de lectura sigue siendo relevante la met\xe1fora?'}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Respuesta"}),': La cr\xedtica es parcialmente v\xe1lida. El estudio de Busjahn et al. (2014) y otros de la Dra. Margaret Burnett (Oregon State University) muestran que los desarrolladores modernos no leen c\xf3digo secuencialmente: navegan por saltos hipertextuales (Ctrl+Click, "Find Usages", "Go to Implementation"). Menos del 15% de las sesiones de lectura son secuenciales top-to-bottom. Sin embargo, la met\xe1fora del peri\xf3dico sigue siendo relevante para: (a) el PRIMER encuentro con una codebase desconocida \u2014cuando no sab\xe9s qu\xe9 es importante, leer de arriba hacia abajo te da el mapa mental, (b) la lectura en herramientas que NO son IDEs: GitHub diffs, code reviews en GitLab, snippets en documentaci\xf3n \u2014donde no ten\xe9s navegaci\xf3n hipertextual y el orden vertical IMPORTA, (c) c\xf3digo que se lee en presentaciones, papers, o en pair programming donde una persona lee en voz alta. La met\xe1fora no deber\xeda descartarse, pero tampoco deber\xeda ser el \xdaNICO principio de organizaci\xf3n. Un c\xf3digo bien organizado para lectura secuencial TAMBI\xc9N funciona bien para navegaci\xf3n hipertextual porque los nombres y la estructura son claros.']}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Por qu\xe9"}),": La clase da la met\xe1fora como verdad revelada. La investigaci\xf3n en HCI y lectura de c\xf3digo muestra que es una simplificaci\xf3n. El alumno debe entender que la Newspaper Metaphor es una buena heur\xedstica de DEFAULT, no una descripci\xf3n precisa de c\xf3mo se lee c\xf3digo en 2026 con herramientas modernas."]}),"\n",(0,s.jsx)(o.hr,{}),"\n",(0,s.jsxs)(o.h3,{id:"10-cuestionar-la-clase-recomienda-no-usar-marcadores-de-posici\xf3n-banners-como---constructors--sin-embargo-en-codebases-de-lenguajes-que-no-tienen-folding-nativo-o-en-scripts-de-shell-estos-banners-siguen-siendo-comunes-en-qu\xe9-contextos-los-banners-de-secci\xf3n-siguen-siendo-defendibles-qu\xe9-dice-la-gu\xeda-de-estilo-de-bash-de-google-al-respecto",children:["10. [Cuestionar] La clase recomienda no usar marcadores de posici\xf3n (banners como ",(0,s.jsx)(o.code,{children:"// ===== CONSTRUCTORS ====="}),"). Sin embargo, en codebases de lenguajes que no tienen folding nativo o en scripts de shell, estos banners siguen siendo comunes. \xbfEn qu\xe9 contextos los banners de secci\xf3n siguen siendo defendibles? \xbfQu\xe9 dice la gu\xeda de estilo de Bash de Google al respecto?"]}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Respuesta"}),": La Google Shell Style Guide (revisi\xf3n 2024) RECOMIENDA el uso de banners de secci\xf3n en scripts de Bash y archivos de configuraci\xf3n largos, porque estos lenguajes no tienen soporte de IDE para folding, outline o navegaci\xf3n por s\xedmbolos. El formato recomendado es: ",(0,s.jsx)(o.code,{children:"### SECTION NAME ##########################################"}),'. Defendible cuando: (a) el lenguaje no tiene facilidades de navegaci\xf3n (Bash, Makefiles, scripts Python independientes sin IDE), (b) el archivo es inherentemente secuencial y largo por naturaleza (Dockerfiles multistage, pipelines de CI/CD, archivos de configuraci\xf3n Terraform), (c) el equipo NO usa un IDE (sysadmins que usan vim/emacs sin plugins). La cr\xedtica de Clean Code a estos banners se aplica correctamente en archivos de C\xd3DIGO FUENTE de lenguajes con IDE (Java, TypeScript, C#), pero se sobregeneraliza. La regla deber\xeda ser: "no uses banners si tu herramienta te da navegaci\xf3n por s\xedmbolos; usalos si tu herramienta no provee estructura visual alternativa".']}),"\n",(0,s.jsxs)(o.p,{children:[(0,s.jsx)(o.strong,{children:"Por qu\xe9"}),": La clase condena los banners sin distinguir contexto de lenguaje/herramienta. El alumno que solo programa en Java con IntelliJ puede aceptar la regla sin cuestionar, pero el que trabaja con infraestructura como c\xf3digo o scripts encontrar\xe1 la regla inaplicable. La gu\xeda de estilo de Google para Bash es una fuente autoritativa que contradice directamente a Clean Code en este punto, demostrando que las reglas de formato son contextual-dependentes."]})]})}function u(e={}){const{wrapper:o}={...(0,i.R)(),...e.components};return o?(0,s.jsx)(o,{...e,children:(0,s.jsx)(d,{...e})}):d(e)}},28453(e,o,a){a.d(o,{R:()=>r,x:()=>t});var n=a(96540);const s={},i=n.createContext(s);function r(e){const o=n.useContext(i);return n.useMemo(function(){return"function"==typeof e?e(o):{...o,...e}},[o,e])}function t(e){let o;return o=e.disableParentContext?"function"==typeof e.components?e.components(s):e.components||s:r(e.components),n.createElement(i.Provider,{value:o},e.children)}}}]);